+	// Favorite button
+	if (favorite_button) {
+		width += favorite_button->get_size().x;
+	}
+	// Project icon
+	if (project_icon) {
+		width += project_icon->get_size().x;
+	}
+	// Right spacer (last child)
+	if (child_count > 0) {
+		Control *right_spacer = Object::cast_to<Control>(get_child(child_count - 1));
+		if (right_spacer) {
+			width += right_spacer->get_size().x;
+		}
+	}
+	return width;
